	[
		'slug'        => 'student-house-move-out-cleaning-hull',
		'title'       => 'Student House Move-Out Cleaning Guide for Hull',
		'seo_title'   => 'Student House Move-Out Cleaning in Hull: Full Guide',
		'description' => 'Student house move-out cleaning in Hull: how to split the work, a shared-house checklist, rubbish and bin day, HMO rules and protecting the group deposit.',
		'category'    => 'end-of-tenancy',
